question: What are all the song names by singers who are older than average?, query SPARQL:

execution_result.cleaned_query:
SELECT DISTINCT ?song_name
WHERE {
  # Calculate the average age
  {
    SELECT (AVG(?age) AS ?avgAge)
    WHERE {
      ?singer :singer\#age ?age .
    }
  } AS ?avgAgeQuery

  # Find singers older than the average age
  ?singer :singer\#age ?age .
  FILTER (?age > ?avgAgeQuery)

  # Get song names for these singers
  ?singer :singer\#song_name ?song_name .
}

